'use client';

import {
  RatingGroup as RatingGroupPrimitive,
  useRatingGroup,
  useRatingGroupContext,
  useRatingGroupItemContext,
} from '@ark-ui/react/rating-group';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef, ReactNode } from 'react';
import { forwardRef } from 'react';
import { RatingStarIcon } from '@/lib/moduix/icons/ui';
import styles from './RatingGroup.module.css';

type RatingGroupSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl';

type RatingGroupRootProps = ComponentProps<typeof RatingGroupPrimitive.Root> & {
  size?: RatingGroupSize;
};

type RatingGroupRootProviderProps = ComponentProps<typeof RatingGroupPrimitive.RootProvider> & {
  size?: RatingGroupSize;
};

type RatingGroupItemIndicatorProps = ComponentProps<'span'>;

const RatingGroupRoot = forwardRef<
  ComponentRef<typeof RatingGroupPrimitive.Root>,
  RatingGroupRootProps
>(function RatingGroupRoot({ className, size = 'md', ...props }, ref) {
  return (
    <RatingGroupPrimitive.Root
      ref={ref}
      data-size={size}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="rating-group-root"
    />
  );
});

const RatingGroupRootProvider = forwardRef<
  ComponentRef<typeof RatingGroupPrimitive.RootProvider>,
  RatingGroupRootProviderProps
>(function RatingGroupRootProvider({ className, size = 'md', ...props }, ref) {
  return (
    <RatingGroupPrimitive.RootProvider
      ref={ref}
      data-size={size}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="rating-group-root-provider"
    />
  );
});

const RatingGroupLabel = forwardRef<
  ComponentRef<typeof RatingGroupPrimitive.Label>,
  ComponentProps<typeof RatingGroupPrimitive.Label>
>(function RatingGroupLabel({ className, ...props }, ref) {
  return (
    <RatingGroupPrimitive.Label
      ref={ref}
      className={clsx(styles.label, className)}
      {...props}
      data-slot="rating-group-label"
    />
  );
});

const RatingGroupControl = forwardRef<
  ComponentRef<typeof RatingGroupPrimitive.Control>,
  ComponentProps<typeof RatingGroupPrimitive.Control>
>(function RatingGroupControl({ className, ...props }, ref) {
  return (
    <RatingGroupPrimitive.Control
      ref={ref}
      className={clsx(styles.control, className)}
      {...props}
      data-slot="rating-group-control"
    />
  );
});

const RatingGroupItem = forwardRef<
  ComponentRef<typeof RatingGroupPrimitive.Item>,
  ComponentProps<typeof RatingGroupPrimitive.Item>
>(function RatingGroupItem({ className, ...props }, ref) {
  return (
    <RatingGroupPrimitive.Item
      ref={ref}
      className={clsx(styles.item, className)}
      {...props}
      data-slot="rating-group-item"
    />
  );
});

const RatingGroupItemIndicator = forwardRef<HTMLSpanElement, RatingGroupItemIndicatorProps>(
  function RatingGroupItemIndicator({ className, children, ...props }, ref) {
    const { half, highlighted } = useRatingGroupItemContext();

    return (
      <span
        ref={ref}
        data-half={half ? '' : undefined}
        data-highlighted={highlighted ? '' : undefined}
        className={clsx(styles.itemIndicator, className)}
        {...props}
        data-slot="rating-group-item-indicator"
      >
        {children ?? (
          <>
            <RatingStarIcon data-slot="rating-group-item-indicator-bg" className={styles.iconBg} />
            <RatingStarIcon data-slot="rating-group-item-indicator-fg" className={styles.iconFg} />
          </>
        )}
      </span>
    );
  },
);

function RatingGroupItems({ children }: { children?: ReactNode }) {
  return (
    <>
      <RatingGroupPrimitive.Context>
        {({ items }) =>
          items.map((item) => (
            <RatingGroupItem key={item} index={item}>
              {children ?? <RatingGroupItemIndicator />}
            </RatingGroupItem>
          ))
        }
      </RatingGroupPrimitive.Context>
    </>
  );
}

const RatingGroup = Object.assign(RatingGroupRoot, {
  Root: RatingGroupRoot,
  RootProvider: RatingGroupRootProvider,
  Context: RatingGroupPrimitive.Context,
  HiddenInput: RatingGroupPrimitive.HiddenInput,
  Label: RatingGroupLabel,
  Control: RatingGroupControl,
  Item: RatingGroupItem,
  ItemContext: RatingGroupPrimitive.ItemContext,
  ItemIndicator: RatingGroupItemIndicator,
  Items: RatingGroupItems,
});

export { RatingGroup, useRatingGroup, useRatingGroupContext, useRatingGroupItemContext };
export type {
  RatingGroupItemIndicatorProps,
  RatingGroupRootProps,
  RatingGroupRootProviderProps,
  RatingGroupSize,
};

@layer moduix.components {
  .root {
    display: inline-flex;
    flex-direction: column;
    gap: var(--moduix-rating-group-root-gap, var(--moduix-spacing-1));
    color: var(--moduix-rating-group-color, var(--moduix-color-muted-foreground));

    &[data-size='xs'] {
      --_rating-group-icon-size: var(--moduix-rating-group-icon-size-xs, var(--moduix-spacing-3-5));
    }

    &[data-size='sm'] {
      --_rating-group-icon-size: var(--moduix-rating-group-icon-size-sm, var(--moduix-spacing-4));
    }

    &[data-size='md'] {
      --_rating-group-icon-size: var(--moduix-rating-group-icon-size-md, var(--moduix-spacing-5));
    }

    &[data-size='lg'] {
      --_rating-group-icon-size: var(--moduix-rating-group-icon-size-lg, var(--moduix-spacing-6));
    }

    &[data-size='xl'] {
      --_rating-group-icon-size: var(--moduix-rating-group-icon-size-xl, var(--moduix-spacing-7));
    }
  }

  .label {
    color: var(--moduix-rating-group-label-color, var(--moduix-color-foreground));
    font-size: var(--moduix-rating-group-label-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-rating-group-label-font-weight, var(--moduix-weight-semibold));
    line-height: var(--moduix-rating-group-label-line-height, var(--moduix-line-height-text-sm));
    user-select: none;

    &[data-disabled] {
      opacity: var(--moduix-rating-group-disabled-opacity, var(--moduix-opacity-disabled));
    }
  }

  .control {
    display: inline-flex;
    align-items: center;
    gap: var(--moduix-rating-group-gap, var(--moduix-spacing-1));

    &[data-disabled] {
      opacity: var(--moduix-rating-group-disabled-opacity, var(--moduix-opacity-disabled));
    }
  }

  .item {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    margin: 0;
    border: 0;
    border-radius: var(--moduix-radius-sm);
    padding: 0;
    background-color: transparent;
    color: inherit;
    line-height: 0;
    cursor: pointer;
    transition:
      color var(--moduix-rating-group-transition, var(--moduix-transition-default)),
      opacity var(--moduix-rating-group-transition, var(--moduix-transition-default));

    &[data-readonly],
    &[data-disabled] {
      cursor: default;
    }

    &[data-disabled] {
      pointer-events: none;
    }

    &[data-focus-visible] {
      outline: var(
          --moduix-rating-group-focus-ring-width,
          var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        )
        solid var(--moduix-rating-group-focus-ring-color, var(--moduix-color-ring));
      outline-offset: var(--moduix-rating-group-focus-ring-offset, var(--moduix-border-width-sm));
    }
  }

  .itemIndicator {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(
      --_rating-group-icon-size,
      var(--moduix-rating-group-icon-size-md, var(--moduix-spacing-5))
    );
    height: var(
      --_rating-group-icon-size,
      var(--moduix-rating-group-icon-size-md, var(--moduix-spacing-5))
    );
    color: var(--moduix-rating-group-active-color, var(--moduix-color-primary));

    & > svg {
      flex: none;
      width: 100%;
      height: 100%;
      transition:
        color var(--moduix-rating-group-transition, var(--moduix-transition-default)),
        fill var(--moduix-rating-group-transition, var(--moduix-transition-default)),
        stroke var(--moduix-rating-group-transition, var(--moduix-transition-default)),
        clip-path var(--moduix-rating-group-transition, var(--moduix-transition-default));
    }

    &[data-half] .iconFg {
      clip-path: inset(0 50% 0 0);
    }

    &:not([data-highlighted]) .iconFg {
      clip-path: inset(0 100% 0 0);
    }
  }

  .item[data-half] .iconFg {
    clip-path: inset(0 50% 0 0);
  }

  .item:not([data-highlighted]) .iconFg {
    clip-path: inset(0 100% 0 0);
  }

  .root:dir(rtl) {
    .itemIndicator[data-half] .iconFg,
    .item[data-half] .iconFg {
      clip-path: inset(0 0 0 50%);
    }
  }

  .iconBg {
    position: absolute;
    inset: 0;
    color: var(--moduix-rating-group-color, var(--moduix-color-muted-foreground));
    fill: transparent;
    stroke: currentColor;
  }

  .iconFg {
    position: absolute;
    inset: 0;
    color: var(--moduix-rating-group-active-color, var(--moduix-color-primary));
    fill: currentColor;
    stroke: currentColor;
    clip-path: inset(0 0 0 0);
  }
}

export {
  RatingGroup,
  useRatingGroup,
  useRatingGroupContext,
  useRatingGroupItemContext,
} from './RatingGroup.js';
export type {
  RatingGroupItemIndicatorProps,
  RatingGroupRootProps,
  RatingGroupRootProviderProps,
  RatingGroupSize,
} from './RatingGroup.js';
